-- 0154_payments_rules_method_account
-- Forward-only migration (rule 34), plan 2B.2 Task 34.8b (owner item 135, 2026-11-09; FX §6; precedents 0142, 0149, 0151). Covered by
-- packages/modules/payments/src/__tests__/method-account.integration.test.ts («(4) migration 0154…»: the file run twice) and
-- packages/modules/accounting/src/__tests__/rules-equal.test.ts (the shipped JSON this file copies). Re-runnable: it rewrites only copies
-- that still equal the 0151 template.
--
-- The bank account of one medio de pago: the cash line of «Recibo de caja» names an ordered list of dimensions (the posting engine of the
-- same task), `payment_method_id:{{methodId}}` first and `payment_method:{{method}}` (the medio's kind, as before) second, so a method
-- mapped to its own account in its «Contabilidad» tab (a USD transfer into the dollar account, 111010) posts there and every other method
-- keeps its kind's account. accounting.posting_rule.sync only adds missing rules, so the copies a company holds are rewritten here: those
-- nobody touched (is_default, not is_modified) whose template is still exactly 0151's. An edited copy keeps resolving by kind (correct for
-- every method without an account of its own). The template below is packages/modules/payments/src/rules/payment-received.json (and its
-- twin in accounting/src/rules/defaults/), verbatim. «Anulación de recibo de caja» reverses the entry (reverseOf) and does not change.

update accounting.posting_rules
   set template = $tpl${"date": "$.date", "description": "Recibo de caja {{number}} · {{customer.legalName}}", "party": "$.customer.partyId", "currency": "$.currency", "exchangeRate": "$.exchangeRate", "source": {"entity": "payments.receipt", "id": "$.paymentId"}, "lines": [{"role": "cash", "side": "debit", "amount": "$.amountDoc", "amountCompany": "$.amount", "dimension": ["payment_method_id:{{methodId}}", "payment_method:{{method}}"]}, {"role": "withholding_income_suffered", "side": "debit", "forEach": "$.withholdings.income[*]", "amount": "$.amountDoc", "amountCompany": "$.amount", "taxCode": "$.code", "taxRate": "$.rate", "taxBase": "$.base"}, {"role": "withholding_vat_suffered", "side": "debit", "forEach": "$.withholdings.vat[*]", "amount": "$.amountDoc", "amountCompany": "$.amount", "taxCode": "$.code", "taxRate": "$.rate", "taxBase": "$.base"}, {"role": "withholding_ica_suffered", "side": "debit", "forEach": "$.withholdings.ica[*]", "amount": "$.amountDoc", "amountCompany": "$.amount", "taxCode": "$.code", "taxRate": "$.rate", "taxBase": "$.base"}, {"role": "fx_loss", "side": "debit", "forEach": "$.allocations[*]", "amount": "0", "amountCompany": "$.fx.loss", "dimension": "fx_kind:realized"}, {"role": "receivable", "side": "credit", "amount": "$.appliedDoc", "amountCompany": "$.applied"}, {"role": "customer_advances", "side": "credit", "forEach": "$.advances[*]", "amount": "$.amountDoc", "amountCompany": "$.amount"}, {"role": "fx_gain", "side": "credit", "forEach": "$.allocations[*]", "amount": "0", "amountCompany": "$.fx.gain", "dimension": "fx_kind:realized"}], "reverseOf": null}$tpl$::jsonb
 where event = 'payments.received' and name = 'Recibo de caja'
   and is_default and not is_modified
   and template = $old${"date": "$.date", "description": "Recibo de caja {{number}} · {{customer.legalName}}", "party": "$.customer.partyId", "currency": "$.currency", "exchangeRate": "$.exchangeRate", "source": {"entity": "payments.receipt", "id": "$.paymentId"}, "lines": [{"role": "cash", "side": "debit", "amount": "$.amountDoc", "amountCompany": "$.amount", "dimension": "payment_method:{{method}}"}, {"role": "withholding_income_suffered", "side": "debit", "forEach": "$.withholdings.income[*]", "amount": "$.amountDoc", "amountCompany": "$.amount", "taxCode": "$.code", "taxRate": "$.rate", "taxBase": "$.base"}, {"role": "withholding_vat_suffered", "side": "debit", "forEach": "$.withholdings.vat[*]", "amount": "$.amountDoc", "amountCompany": "$.amount", "taxCode": "$.code", "taxRate": "$.rate", "taxBase": "$.base"}, {"role": "withholding_ica_suffered", "side": "debit", "forEach": "$.withholdings.ica[*]", "amount": "$.amountDoc", "amountCompany": "$.amount", "taxCode": "$.code", "taxRate": "$.rate", "taxBase": "$.base"}, {"role": "fx_loss", "side": "debit", "forEach": "$.allocations[*]", "amount": "0", "amountCompany": "$.fx.loss", "dimension": "fx_kind:realized"}, {"role": "receivable", "side": "credit", "amount": "$.appliedDoc", "amountCompany": "$.applied"}, {"role": "customer_advances", "side": "credit", "forEach": "$.advances[*]", "amount": "$.amountDoc", "amountCompany": "$.amount"}, {"role": "fx_gain", "side": "credit", "forEach": "$.allocations[*]", "amount": "0", "amountCompany": "$.fx.gain", "dimension": "fx_kind:realized"}], "reverseOf": null}$old$::jsonb;
